    'VulnerabilityManagementExtraDesc'    => '弱點管理 Extra 讓客戶能夠將其 SimpleRisk 實例與 Qualys、Tenable.io 或 Rapid7 Nexpose/InsightVM 整合，並將資產和弱點資料匯入 SimpleRisk。接著，您可以選擇要涵蓋的站點，決定要匯入哪些弱點分數，並對哪些弱點要轉為風險加以追蹤進行分類處理。',
