    'CustomAuthenticationExtraDesc'       => '自訂身份驗證擴充模組提供對 Active Directory 和 SAML 驗證的支援。在 SimpleRisk Core 產品中，如果沒有此擴充模組，則只能在 SimpleRisk 身分識別儲存庫中建立新使用者。',
    'EncryptionExtraDesc'                 => '加密資料庫附加功能會產生一個隨機的 AES-256 位元加密金鑰，並使用該金鑰對敏感文字進行加密，然後再將其插入 SimpleRisk 資料庫。這樣可以防止任何人在未直接使用 SimpleRisk 應用程式的情況下查看或修改資料。',
    'OrganizationManagementDesc'          => '組織階層 Extra 讓您能夠定義多個業務單位，每個業務單位可包含任意數量的團隊。接著可以將使用者指派到各業務單位下的一個或多個團隊。這會影響使用者查看和使用與其無關聯的團隊、使用者及資產的能力。',

    // Configure Hub - tile descriptions (data category)
