    'ImportExportExtraDesc'               => '匯入匯出 Extra 提供將 CSV 檔案中的欄位對應到 SimpleRisk 資料庫欄位，以將資料匯入 SimpleRisk 的功能。它可用於匯入來自第三方試算表的稽核結果、來自其他工具的弱點掃描結果、來自 CMDB 的資產等。此 Extra 也能從 SimpleRisk 匯出包含風險、緩解、審查或三者合併報告的 CSV 檔案。',
    'JiraExtraDesc'                       => 'Jira 整合 Extra 讓使用者能夠與 Jira 實例進行雙向整合。它支援將風險連結到 Jira 問題，並同步其資料、狀態和評論。',
    'APIExtraDesc'                        => 'API Extra 讓客戶能夠使用 RESTful API 與其他應用程式建立指令碼化互動，以實現進階自動化並善用現有基礎架構。',
    'AdvancedSearchExtraDesc'             => "進階搜尋擴充功能將頂部欄的搜尋框擴展為一個跨風險、框架、控制措施、文件、例外情況、測試、稽核、資產和資產群組的搜尋框，並提供一個完整的搜尋頁面供使用者瀏覽搜尋結果。它僅顯示使用者有權查看的記錄。",
    'AssessmentsExtraDesc'                => '風險評估 Extra 讓使用者能夠定義聯絡人、建立問題（包括邏輯）、使用問卷範本組合多個問題、建立問卷並發送給聯絡人、查看問卷結果、根據這些結果新增風險、比較不同時間的結果、匯入和匯出外部自訂的評估，以及審查風險評估稽核軌跡。',
    'ActiveAssessmentsDesc'               => '查看和管理目前正在進行的評估。',
    'WorkflowsExtraDesc'                  => '工作流程 Extra 提供視覺化、事件驅動的工作流程引擎，可針對 SimpleRisk 內的事件自動執行風險管理動作。您可以設計在變更時觸發的工作流程——例如風險被提交、更新或審查——以路由批准、指派工作，並在無需人工介入的情況下讓流程持續推進。',

