    'SoaFrameworkInactiveTitle' => '此框架未啟用',
    'SoaFrameworkInactiveBody' => '適用性聲明描述組織目前所運作的範圍。請重新啟用該框架以產生聲明。',
    'SoaFrameworkNotFoundBody' => '該框架已不存在。',

    // A framework with no controls mapped into it. Not an error -- it is a real
