    "AttackVectorHelp" => '漏洞可被存取的方式。
• 本機：需要本機存取，例如主控台或 shell。
• 相鄰網路：攻擊者必須位於相同的實體或邏輯網路區段。
• 網路：可透過網路遠端利用，無需本機或相鄰存取。',
    "AttackComplexityHelp" => "攻擊者獲得目標存取權限後，攻擊的複雜程度。\n• 高：需要難以達成的特殊條件。\n• 中：需要滿足一些條件，但一旦滿足，利用起來並不困難。\n• 低：無特殊條件。",
    "AuthenticationHelp" => '攻擊者為利用目標而必須對其進行驗證的次數。
• 多次：需要驗證兩次或以上，即使使用相同的憑證。
• 單次：需要驗證一次。
• 無：不需要驗證。',
    "ConfidentialityImpactHelp" => '若被利用，對系統所處理資料機密性的影響。
• 無：沒有影響。
• 部分：部分資訊遭洩露，但攻擊者無法控制洩露內容，或損失有限。
• 完全：系統上的所有資訊全部洩露。',
    "IntegrityImpactHelp" => "漏洞利用後對系統完整性的影響。\n• 無：無影響。\n• 部分：部分資料可修改，但攻擊者無法控制修改內容，或修改範圍有限。\n• 完全：系統完整性完全喪失；攻擊者可以修改任何檔案。",
    "AvailabilityImpactHelp" => '若被利用，對系統可用性的影響。
• 無：沒有影響。
• 部分：效能降低或可用性中斷。
• 完全：受影響的資源完全停止運作。',
    "RemediationLevelHelp" => "針對此漏洞的可用修復等級。\n• 官方修復：提供完整的廠商解決方案。\n• 暫時修復：提供官方的暫時修復方案。\n• 變通方案：存在非官方的非廠商變通方案。\n• 無可用方案：沒有可用的解決方案，或無法套用任何解決方案。",
    "ReportConfidenceHelp" => '對漏洞存在及其技術細節可信度的信心程度。
• 未確認：僅有單一未經確認的來源報告；根本問題屬於推測。
• 未證實：多個獨立來源回報相同行為，但根本原因尚未確認。
• 已確認：供應商已承認該問題，或已透過原始碼或攻擊程式分析確認。',
    "CollateralDamagePotentialHelp" => '若漏洞被利用，造成生命損失、實體資產損失或財務損失的可能性。
• 無：不太可能造成此類損失。
• 低至中：可能造成中等程度的損失。
• 高：對組織的資產、營收或安全造成災難性的影響。',
    "TargetDistributionHelp" => "您環境中易受攻擊系統的比例。\n• 無：不存在目標系統。\n• 低：1-25% 的系統易受攻擊。\n• 中：26-75% 的系統易受攻擊。\n• 高：76-100% 的系統易受攻擊。",
    "ConfidentialityRequirementHelp" => '受影響資產的機密性對您的組織有多重要。
• 低：機密性喪失的影響有限。
• 中：會造成嚴重影響。
• 高：會造成災難性影響。',
    "IntegrityRequirementHelp" => "受影響資產的完整性對貴組織的重要性為何？\n• 低：完整性損失的影響有限。\n• 中：影響嚴重。\n• 高：影響災難性。",
    "AvailabilityRequirementHelp" => '受影響資產的可用性對您的組織有多重要。
