    'EnvironmentalScoreMetricsDescription' => '此漏洞的風險取決於您的環境：實際損害的可能性，以及有多少系統實際受到影響。',
    'ImpactSubscoreModifiersDescription' => '根據機密性、完整性和可用性對此特定資產的實際重要程度,為基本分數的影響加權。',
