    'DamagePotentialHelp' => '如果發生安全漏洞利用，會造成多大的損失？' . "\n" . '0 = 無' . "\n" . '5 = 個人用戶資料遭到外洩或影響。' . "\n" . '10 = 系統或資料完全銷毀',
    'ReproducibilityHelp' => '重現該威脅利用有多容易？
0 = 非常困難或不可能，即使是應用程式的管理員也一樣。
