    'ExploitabilityHelp' => '利用這種威脅需要什麼？' . "\n" . '0 = 具備高階程式設計和網路知識，以及自訂或進階攻擊工具。' . "\n" . '5 = 網路上存在惡意軟體，或使用現有的攻擊工具很容易進行攻擊。' . "\n" . '10 = 只是一個網頁瀏覽器',
    'AffectedUsersHelp' => '有多少使用者會受到影響？
