    'DiscoverabilityHelp' => '發現這種威脅有多容易？' . "\n" . '0 = 非常困難甚至不可能；需要原始碼或管理員權限。' . "\n" . '5 = 可以透過猜測或監控網路追蹤來找出答案。' . "\n" . '9 = 此類故障的詳細資訊已公開，可以使用搜尋引擎輕鬆找到。' . "\n" . '10 = 此資訊顯示在網頁瀏覽器網址列或表單中。',
