    'EaseOfDiscoveryHelp' => '這群攻擊者要發現這個漏洞有多容易？' . "\n" . '1 = 幾乎不可能' . "\n" . '3 = 困難' . "\n" . '7 = 簡單' . "\n" . '9 = 可用的自動化工具',
    'EaseOfExploitHelp' => '這群攻擊者利用此漏洞有多容易？' . "\n" . '1 = 理論值' . "\n" . '3 = 困難' . "\n" . '5 = 簡單' . "\n" . '9 = 可用的自動化工具',
