    'IntrusionDetectionHelp' => '漏洞利用被偵測到的可能性有多大？' . "\n" . '1 = 應用中的主動偵測' . "\n" . '3 = 已記錄並審核' . "\n" . '8 = 未經審核已記錄' . "\n" . '9 = 未記錄',
    'LossOfConfidentialityHelp' => '可能洩露多少資料，這些資料的敏感程度如何？
